	/// <summary>植物键 → 获取关卡（查表；找不到 = 空）。</summary>
	internal static string LevelOf(string plantKey)
	{
		foreach (string line in LevelSourceLines)
		{
			int i = line.IndexOf('|');
			if (i > 0 && line.Substring(0, i) == plantKey)
			{
				return line.Substring(i + 1);
			}
		}
		return "";
	}
